/////////////////////////////////
// cp_priority_s
//   With hvip = hie = 0x444, hideleg = 0 and sie = 1s, raise SEI, STI, SSI or nothing, then set
//   sstatus.SIE.  The S-level interrupt is taken first, then VSEI, VSSI and VSTI
/////////////////////////////////
  csrw hideleg, zero
  LI(x6, MIP_VS_MASK)
  csrw hvip, x6
  csrw hie, x6
  LI(x6, -1)
  csrw sie, x6
  RVTEST_SET_SEXT_INT_S
  RVTEST_IDLE_FOR_INTERRUPT(x6)
InterruptsH_hs_cg_cp_priority_s_sei:
  csrr x6, sip
  # Check if x6 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x6, InterruptsH_hs_cg_cp_priority_s_sei, InterruptsH_hs_cg_cp_priority_s_sei_str)
  csrsi sstatus, SSTATUS_SIE
  RVTEST_IDLE_FOR_INTERRUPT(x6)
  csrci sstatus, SSTATUS_SIE
  RVTEST_CLR_SEXT_INT_S
  csrw sie, zero
  csrw hvip, zero
  LI(x6, MIP_VS_MASK)
  csrw hvip, x6
  csrw hie, x6
  LI(x6, -1)
  csrw sie, x6
  RVTEST_SET_STIME_INT_S
  RVTEST_IDLE_FOR_INTERRUPT(x6)
InterruptsH_hs_cg_cp_priority_s_sti:
  csrr x6, sip
  # Check if x6 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x6, InterruptsH_hs_cg_cp_priority_s_sti, InterruptsH_hs_cg_cp_priority_s_sti_str)
  csrsi sstatus, SSTATUS_SIE
  RVTEST_IDLE_FOR_INTERRUPT(x6)
  csrci sstatus, SSTATUS_SIE
  RVTEST_CLR_STIME_INT_S
  csrw sie, zero
  csrw hvip, zero
  LI(x6, MIP_VS_MASK)
  csrw hvip, x6
  csrw hie, x6
  LI(x6, -1)
  csrw sie, x6
  RVTEST_SET_SSW_INT_S
  RVTEST_IDLE_FOR_INTERRUPT(x6)
InterruptsH_hs_cg_cp_priority_s_ssi:
  csrr x6, sip
  # Check if x6 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x6, InterruptsH_hs_cg_cp_priority_s_ssi, InterruptsH_hs_cg_cp_priority_s_ssi_str)
  csrsi sstatus, SSTATUS_SIE
