/////////////////////////////////
// cp_priority_lcofi
//   With hvip = hie = 0x444, hideleg = 0 and sie.LCOFIE = 1, raise LCOFI, then set sstatus.SIE.
//   HS-mode takes VSEI, VSSI and VSTI, then LCOFI
/////////////////////////////////
#ifdef SSCOFPMF_SUPPORTED
  csrw hideleg, zero
