  RVTEST_SIGUPD(x2, x5, x4, x13, InterruptsH_hs_cg_cp_priority_lcofi_lcofi, InterruptsH_hs_cg_cp_priority_lcofi_lcofi_str)
  csrsi sstatus, SSTATUS_SIE
